import * as React from 'react'
import type { Meta, StoryObj } from '@storybook/react'
import { expect, fn, userEvent, within } from '@storybook/test'

import { Badge } from './badge'
import { DataTableBase, type DataTableColumn } from './data-table-base'
import { InputCurrency } from './input-currency'

interface PrimitiveStoryArgs {
  onAmountChange: (value: number | null) => void
  onSort: (columnId: string, direction: 'asc' | 'desc') => void
  onRowActivate: (row: SampleRow) => void
}

interface SampleRow { id: string; date: string; reference: string; account: string; state: string; amount: number }

const rows: SampleRow[] = [
  { id: '1', date: '2026-08-25', reference: 'INV-1049', account: '200 · Sales Revenue', state: 'Reconciled', amount: 18480 },
  { id: '2', date: '2026-08-25', reference: 'BAS-Q4-26', account: '310 · GST Clearing', state: 'Pending', amount: -42870.4 },
  { id: '3', date: '2026-08-24', reference: 'JE-07204', account: '825 · Suspense', state: 'Unmatched', amount: -861.55 }
]

const columns: DataTableColumn<SampleRow>[] = [
  { id: 'date', header: 'Date', accessor: 'date', width: '112px', financial: true, sortable: true },
  { id: 'reference', header: 'Reference', accessor: 'reference', width: '120px', financial: true, sortable: true },
  { id: 'account', header: 'Account', accessor: 'account', width: '220px' },
  { id: 'state', header: 'State', width: '110px', cell: (row) => <Badge tone={row.state === 'Reconciled' ? 'credit' : 'suspense'} indicator>{row.state}</Badge> },
  { id: 'amount', header: 'Amount', accessor: 'amount', width: '140px', align: 'right', financial: true, sortable: true, cell: (row) => `${row.amount < 0 ? '−' : ''}$${Math.abs(row.amount).toFixed(2)}` }
]

const meta: Meta<PrimitiveStoryArgs> = {
  title: 'Foundation/System Primitives',
  tags: ['autodocs'],
  parameters: { docs: { description: { component: 'Atomic contracts for monetary entry, semantic status, and dense tabular work. All primitives expose typed value and interaction callbacks.' } } },
  args: { onAmountChange: fn(), onSort: fn(), onRowActivate: fn() },
  argTypes: { onAmountChange: { action: 'amount changed' }, onSort: { action: 'table sorted' }, onRowActivate: { action: 'row activated' } }
}

export default meta
type Story = StoryObj<typeof meta>

function CurrencySpecimen({ onAmountChange }: Pick<PrimitiveStoryArgs, 'onAmountChange'>) {
  const [value, setValue] = React.useState<number | null>(1248039.2)
  return <div className="grid max-w-2xl grid-cols-1 gap-4 border bg-card p-4 sm:grid-cols-2"><label className="text-[11px]"><span className="mb-1.5 block font-semibold">Invoice total · dense</span><InputCurrency value={value} onValueChange={(next) => { setValue(next); onAmountChange(next) }} currency="AUD" /></label><label className="text-[11px]"><span className="mb-1.5 block font-semibold">Invalid allocation · standard</span><InputCurrency defaultValue={-8412.9} invalid density="standard" currency="AUD" aria-describedby="allocation-error" /><span id="allocation-error" className="mt-1 block text-[10px] text-financial-debit">Allocation exceeds the unassigned balance.</span></label></div>
}

export const CurrencyInput: Story = {
  render: (args) => <CurrencySpecimen onAmountChange={args.onAmountChange} />,
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement)
    const input = canvas.getAllByLabelText('Amount in AUD')[0]
    await userEvent.clear(input)
    await userEvent.type(input, '2500.75')
    await userEvent.tab()
    await expect(input).toHaveValue('2,500.75')
  }
}

export const SemanticBadges: Story = {
  render: () => <div className="flex flex-wrap gap-2 border bg-card p-4"><Badge tone="credit" indicator>Reconciled</Badge><Badge tone="debit" indicator>Overdue</Badge><Badge tone="suspense" indicator>Unmatched</Badge><Badge tone="audit" indicator>OCR 98%</Badge><Badge tone="neutral">Archived</Badge></div>
}

export const DenseTableEngine: Story = {
  render: (args) => <DataTableBase className="max-w-4xl" caption="Financial table primitive specimen" columns={columns} rows={rows} getRowId={(row) => row.id} initialSort={{ columnId: 'date', direction: 'desc' }} onSort={args.onSort} onRowActivate={args.onRowActivate} />,
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement)
    await userEvent.click(canvas.getByRole('button', { name: /Amount/i }))
    await expect(canvas.getByRole('columnheader', { name: /Amount/i })).toHaveAttribute('aria-sort', 'ascending')
    const firstCell = canvas.getAllByRole('cell')[0]
    firstCell.focus()
    await userEvent.keyboard('{ArrowDown}{Enter}')
    await expect(args.onRowActivate).toHaveBeenCalledTimes(1)
  }
}

export const TableStates: Story = {
  render: () => <div className="grid gap-4"><DataTableBase caption="Loading journal" columns={columns} rows={[]} getRowId={(row) => row.id} loading /><DataTableBase caption="Unavailable journal" columns={columns} rows={[]} getRowId={(row) => row.id} error="Projection cursor is unavailable. Posting is paused until reconciliation completes." /><DataTableBase caption="Empty journal" columns={columns} rows={[]} getRowId={(row) => row.id} /></div>
}
