'use client'

import * as React from 'react'

import { cn } from '@/lib/utils'

export interface InputCurrencyProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'defaultValue' | 'onChange' | 'size' | 'value'> {
  currency?: string
  locale?: string
  value?: number | null
  defaultValue?: number | null
  onValueChange?: (value: number | null) => void
  invalid?: boolean
  density?: 'dense' | 'standard'
  showCurrencyCode?: boolean
}

function numberFormatter(locale: string, maximumFractionDigits: number) {
  return new Intl.NumberFormat(locale, {
    minimumFractionDigits: maximumFractionDigits,
    maximumFractionDigits,
    useGrouping: true
  })
}

function currencySymbol(currency: string, locale: string) {
  return new Intl.NumberFormat(locale, { style: 'currency', currency, currencyDisplay: 'narrowSymbol' })
    .formatToParts(0)
    .find((part) => part.type === 'currency')?.value ?? currency
}

function parseCurrency(value: string) {
  const normalized = value.replace(/[^\d.-]/g, '')
  if (!normalized || normalized === '-' || normalized === '.' || normalized === '-.') return null
  const parsed = Number(normalized)
  return Number.isFinite(parsed) ? parsed : null
}

export const InputCurrency = React.forwardRef<HTMLInputElement, InputCurrencyProps>(
  ({
    className,
    currency = 'AUD',
    locale = 'en-AU',
    value,
    defaultValue = null,
    onValueChange,
    onBlur,
    onFocus,
    invalid = false,
    density = 'dense',
    showCurrencyCode = true,
    disabled,
    'aria-label': ariaLabel,
    'aria-describedby': ariaDescribedBy,
    ...props
  }, ref) => {
    const controlled = value !== undefined
    const [internalValue, setInternalValue] = React.useState<number | null>(defaultValue)
    const [focused, setFocused] = React.useState(false)
    const [draft, setDraft] = React.useState('')
    const currentValue = controlled ? value : internalValue
    const decimals = currency === 'JPY' ? 0 : 2
    const formatter = React.useMemo(() => numberFormatter(locale, decimals), [decimals, locale])
    const symbol = React.useMemo(() => currencySymbol(currency, locale), [currency, locale])

    const setNextValue = (next: number | null) => {
      if (!controlled) setInternalValue(next)
      onValueChange?.(next)
    }

    const displayValue = focused
      ? draft
      : currentValue === null || currentValue === undefined
        ? ''
        : formatter.format(currentValue)

    return (
      <div
        className={cn(
          'group inline-flex w-full items-center rounded-[var(--spatial-radius-strict)] border bg-background transition-[border-color,box-shadow] focus-within:border-ring focus-within:ring-1 focus-within:ring-ring',
          density === 'dense' ? 'h-row-dense' : 'h-row-standard',
          invalid && 'border-financial-debit focus-within:border-financial-debit focus-within:ring-financial-debit',
          disabled && 'cursor-not-allowed bg-muted opacity-60',
          className
        )}
      >
        <span aria-hidden className="financial-data pl-2 text-[11px] text-muted-foreground">{symbol}</span>
        <input
          ref={ref}
          inputMode="decimal"
          value={displayValue}
          disabled={disabled}
          aria-label={ariaLabel ?? `Amount in ${currency}`}
          aria-describedby={ariaDescribedBy}
          aria-invalid={invalid || undefined}
          onFocus={(event) => {
            setFocused(true)
            setDraft(currentValue === null || currentValue === undefined ? '' : String(currentValue))
            onFocus?.(event)
          }}
          onChange={(event) => {
            setDraft(event.target.value)
            setNextValue(parseCurrency(event.target.value))
          }}
          onBlur={(event) => {
            setFocused(false)
            onBlur?.(event)
          }}
          className={cn(
            'financial-data h-full min-w-0 flex-1 border-0 bg-transparent px-1.5 text-right text-[12px] font-medium outline-none placeholder:font-sans placeholder:text-muted-foreground',
            typeof currentValue === 'number' && currentValue < 0 && 'text-financial-debit'
          )}
          {...props}
        />
        {showCurrencyCode && <span className="financial-data border-l px-2 text-[10px] text-muted-foreground">{currency}</span>}
      </div>
    )
  }
)
InputCurrency.displayName = 'InputCurrency'
